    # Ensure no knowledge-base helper functions are assumed/used (the provided <functions> list is empty).

    # Navigate directly to the product edit page for the existing product 2799 using a relative URL.
    await page.goto("/index.php/admin/catalog_product/edit/id/2799/")
    await page.wait_for_load_state("networkidle")

    # 1) Set General attributes if present: Size -> S and Color -> Blue
    # Open General tab if there's a link/tab for it. Use a tolerant approach: try a few roles.
    if await page.get_by_role("link", name="General").count() > 0:
        await page.get_by_role("link", name="General").click()
        await page.wait_for_timeout(300)
    elif await page.get_by_role("tab", name="General").count() > 0:
        await page.get_by_role("tab", name="General").click()
        await page.wait_for_timeout(300)

    # Size attribute
    try:
        if await page.get_by_label("Size").count() > 0:
            try:
                await page.get_by_label("Size").select_option(label="S")
            except Exception:
                # fallback to radio option named "S"
                if await page.get_by_role("radio", name="S").count() > 0:
                    await page.get_by_role("radio", name="S").check()
    except Exception:
        pass

    # Color attribute
    try:
        if await page.get_by_label("Color").count() > 0:
            try:
                await page.get_by_label("Color").select_option(label="Blue")
            except Exception:
                if await page.get_by_role("radio", name="Blue").count() > 0:
                    await page.get_by_role("radio", name="Blue").check()
    except Exception:
        pass

    # 2) Ensure Price is set to 60 in Prices tab
    if await page.get_by_role("link", name="Prices").count() > 0:
        await page.get_by_role("link", name="Prices").click()
        await page.wait_for_timeout(300)
    elif await page.get_by_role("tab", name="Prices").count() > 0:
        await page.get_by_role("tab", name="Prices").click()
        await page.wait_for_timeout(300)

    # Fill Price using an exact label if possible to avoid ambiguous matches
    try:
        price_exact = page.get_by_label("Price *", exact=True)
        if await price_exact.count() == 1:
            await price_exact.fill("60")
        else:
            price_generic = page.get_by_label("Price")
            if await price_generic.count() == 1:
                await price_generic.fill("60")
    except Exception:
        pass

    # 3) Open Inventory tab and set Qty=50 and Stock Availability=In Stock
    if await page.get_by_role("link", name="Inventory").count() > 0:
        await page.get_by_role("link", name="Inventory").click()
        await page.wait_for_timeout(300)
    elif await page.get_by_role("tab", name="Inventory").count() > 0:
        await page.get_by_role("tab", name="Inventory").click()
        await page.wait_for_timeout(300)

    # Fill Qty (try several label variants, preferring exact matches)
    try:
        qty_loc = page.get_by_label("Qty", exact=True)
        if await qty_loc.count() == 1:
            await qty_loc.fill("50")
        else:
            qty_loc2 = page.get_by_label("Qty*")
            if await qty_loc2.count() == 1:
                await qty_loc2.fill("50")
            else:
                qty_alt = page.get_by_label("Quantity", exact=True)
                if await qty_alt.count() == 1:
                    await qty_alt.fill("50")
                else:
                    # final fallback: fill a single Qty-labeled control if it's the only match
                    qty_generic = page.get_by_label("Qty")
                    if await qty_generic.count() == 1:
                        await qty_generic.fill("50")
    except Exception:
        pass

    # Set Stock Availability -> In Stock
    try:
        if await page.get_by_label("Stock Availability").count() > 0:
            try:
                await page.get_by_label("Stock Availability").select_option(label="In Stock")
            except Exception:
                if await page.get_by_role("radio", name="In Stock").count() > 0:
                    await page.get_by_role("radio", name="In Stock").check()
